const d = msg.payload;
if (!d || typeof d.suhu !== 'number' || typeof d.kelembaban !== 'number') {
    node.warn('Payload sensor tidak valid, diabaikan');
    return null;
}
const th = flow.get('threshold') || { max: 30 };
d.received = new Date().toISOString();
d.threshold = th.max;
d.over_threshold = d.suhu > th.max;
flow.set('lastSensor', d);

// Output 1: ke debug / database
msg.payload = d;

// Output 2: broadcast WebSocket (data sensor)
const wsMsg = { payload: { type: 'sensor', data: d } };

// Output 3: notifikasi, hanya saat status berubah (normal <-> melewati batas)
let alertMsg = null;
const wasOver = flow.get('overState') || false;
if (d.over_threshold !== wasOver) {
    flow.set('overState', d.over_threshold);
    alertMsg = { topic: 'iot/notifikasi', payload: {
        type: 'alert',
        level: d.over_threshold ? 'danger' : 'ok',
        message: d.over_threshold
            ? 'Suhu ' + d.suhu + ' C melewati batas ' + th.max + ' C'
            : 'Suhu kembali normal (' + d.suhu + ' C)',
        suhu: d.suhu, threshold: th.max, time: d.received
    }};
}
return [msg, wsMsg, alertMsg];

const d = msg.payload;
const esc = s => String(s).replace(/'/g, "''");
msg.topic = "INSERT INTO sensor_history (suhu,kelembaban,timestamp,received) VALUES ("
  + Number(d.suhu) + "," + Number(d.kelembaban) + ",'" + esc(d.timestamp || '') + "','" + esc(d.received) + "');";
return msg;

const KEY = env.get('API_KEY') || 'iot-kampus-2026';
const CORS = {'Access-Control-Allow-Origin': '*'};
if (msg.req.headers['x-api-key'] !== KEY) {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key tidak valid atau tidak ada (header X-API-Key)'};
    msg.headers = CORS;
    return msg;
}
const data = flow.get('lastSensor') || {suhu: null, kelembaban: null, timestamp: null};
msg.statusCode = 200;
msg.payload = {status: 'success', data: data, server_time: new Date().toISOString()};
msg.headers = CORS;
return msg;

const KEY = env.get('API_KEY') || 'iot-kampus-2026';
const CORS = {'Access-Control-Allow-Origin': '*'};
if (msg.req.headers['x-api-key'] !== KEY) {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key tidak valid atau tidak ada (header X-API-Key)'};
    msg.headers = CORS;
    return [null, msg];
}
msg.topic = "SELECT suhu,kelembaban,timestamp,received FROM sensor_history ORDER BY id DESC LIMIT 50;";
return [msg, null];

const CORS = {'Access-Control-Allow-Origin': '*'};
const rows = Array.isArray(msg.payload) ? msg.payload.slice().reverse() : [];
msg.statusCode = 200;
msg.payload = {status: 'success', count: rows.length, data: rows};
msg.headers = CORS;
return msg;

const KEY = env.get('API_KEY') || 'iot-kampus-2026';
const CORS = {'Access-Control-Allow-Origin': '*'};
if (msg.req.headers['x-api-key'] !== KEY) {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key tidak valid atau tidak ada (header X-API-Key)'};
    msg.headers = CORS;
    return [msg, null];
}
const body = msg.payload || {};
const action = String(body.action || '').toLowerCase();
if (!body.device || !['on', 'off'].includes(action)) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: "device wajib diisi dan action harus 'on' atau 'off'"};
    msg.headers = CORS;
    return [msg, null];
}
const cmd = {device: body.device, action: action};
const mqttMsg = {topic: 'iot/kontrol', payload: cmd};
msg.statusCode = 200;
msg.payload = {status: 'success', message: 'Perintah terkirim', sent: cmd};
msg.headers = CORS;
return [msg, mqttMsg];

const KEY = env.get('API_KEY') || 'iot-kampus-2026';
const CORS = {'Access-Control-Allow-Origin': '*'};
if (msg.req.headers['x-api-key'] !== KEY) {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key tidak valid atau tidak ada (header X-API-Key)'};
    msg.headers = CORS;
    return msg;
}
const th = flow.get('threshold') || { max: 30 };
msg.statusCode = 200;
msg.payload = {status: 'success', data: th};
msg.headers = CORS;
return msg;

const KEY = env.get('API_KEY') || 'iot-kampus-2026';
const CORS = {'Access-Control-Allow-Origin': '*'};
if (msg.req.headers['x-api-key'] !== KEY) {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key tidak valid atau tidak ada (header X-API-Key)'};
    msg.headers = CORS;
    return msg;
}
const max = Number((msg.payload || {}).max);
if (!isFinite(max) || max < -50 || max > 150) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'max harus angka antara -50 dan 150'};
    msg.headers = CORS;
    return msg;
}
flow.set('threshold', { max: max });
msg.statusCode = 200;
msg.payload = {status: 'success', message: 'Batas suhu diperbarui', data: { max: max }};
msg.headers = CORS;
return msg;
